//! Shared initial source only for independent complete original appearance comparisons.
pub const CASES:&[&str]=&["setters_and_overlays","override_alias","inherited_owning","runtime_lifecycle"];
pub fn files(case:&str)->Option<Vec<(&'static str,Vec<u8>)>>{if !CASES.contains(&case){return None}let mut files=vec![("p.dme",b"#include \"code/probe.dm\"\n".to_vec()),("code/probe.dm",b"/proc/probe()\n    return 1\n".to_vec()),("code/unit_tests/quiet.dm",b"// genuine selected unit-test source\n".to_vec()),("tools/ci/lint_scopes.toml",b"[lint.\"sys/appearance\"]\n".to_vec()),("code/declared.dm",b"OM_FIELD(/obj/probe, on, 0, CHANGE)\nAPPEARANCE_WATCH(/obj/probe, list(\"on\"))\n/obj/probe\n    var/on\n".to_vec())];match case{
"setters_and_overlays"=>{files.push(("code/raw.dm",b"/obj/probe/proc/set_on(value)\n    on=value\n    update_icon()\n/obj/probe/proc/raw()\n    set_on(1)\n    update_icon()\n".to_vec()));files.push(("maps/raw.dm",b"/obj/probe/proc/appearance_overlays()\n    overlays += list(1)\n    set_on(2)\n".to_vec()));},
"override_alias"=>files.push(("code/raw.dm",b"// ALLOW(sys_update_icon): the immutable source fixture retains this override\n/obj/probe/update_icon()\n    return\n/obj/probe/appearance_overlays()\n    overlays += list(1) // ALLOW(sys_update_icon): this alias must not hide a different appearance rule\n".to_vec())),
"inherited_owning"=>{files.push(("code/base.dm",b"/obj/probe/proc/process()\n    set_on(1)\n".to_vec()));files.push(("maps/raw.dm",b"/obj/probe/child/process()\n    ..()\n    update_icon()\n".to_vec()));},
"runtime_lifecycle"=>{files.push(("code/datums/sys/appearance.dm",b"/obj/probe/update_icon()\n    set_on(1)\n    update_icon()\n".to_vec()));files.push(("code/lifecycle.dm",b"/obj/probe/Initialize()\n    set_on(1)\n    update_icon()\n".to_vec()));files.push(("maps/raw.dm",b"/obj/probe/update_icon()\n    return\n".to_vec()));},_=>return None}Some(files)}
